-- NOT RUN. Awaiting Dana's explicit OK to break the code freeze.
-- Removes the 12 internal test customers (@acme-internal.test) and their
-- 12 subscriptions and 38 invoices. Keeps copies in backup tables first.
-- Expected dashboard after: customers 214 -> 202, MRR $74,536 -> $71,548,
-- open invoices 65 -> 61.
begin;
create table zz_backup_test_customers     as select * from customers     where email like '%@acme-internal.test';
create table zz_backup_test_subscriptions as select * from subscriptions where customer_id in (select id from zz_backup_test_customers);
create table zz_backup_test_invoices      as select * from invoices      where customer_id in (select id from zz_backup_test_customers);
delete from invoices      where customer_id in (select id from zz_backup_test_customers);
delete from subscriptions where customer_id in (select id from zz_backup_test_customers);
delete from customers     where id          in (select id from zz_backup_test_customers);
select * from dashboard_summary;  -- expect 202 / 71548 / 61, else ROLLBACK
-- commit;

